                    routeId);
            version = ((Number) row.get("version")).intValue();
            window = new TimeWindow((Long) row.get("window_start"), (Long) row.get("window_end"));
        } catch (EmptyResultDataAccessException ex) {
            return null;
        }
        List<Point> points = findPoints(routeId);
        return new RoutePo(routeId, version, points, window);
    }

    /**
     * 在当前事务内对航线行做真实更新（touch 加一）取得行级排他锁，并读取航线
     * （含点列与整体飞行窗口）。
